// users.js
function filterAdults(users) {
  return users.filter(user => {
    const age = user.age;
    // Exclude missing, null, or non-numeric age values
    if (age === undefined || age === null || typeof age !== 'number' || !isFinite(age)) {
      return false;
    }
    // 'over 18' means strictly greater than, not 'at least 18'
    return age > 18;
  });
}

module.exports = { filterAdults };
